using Essco.Application.HumanResources;
namespace Essco.Infrastructure.Data; public sealed class UnavailableEmployeeMovementRepository : IEmployeeMovementRepository { private static ValueTask<int> E() => ValueTask.FromException<int>(new InvalidOperationException("Recursos humanos no está configurado.")); public ValueTask<int> SaveVacationAsync(VacationInput x, CancellationToken t) => E(); public ValueTask<int> SaveDisabilityAsync(DisabilityInput x, CancellationToken t) => E(); public ValueTask<int> SaveDeductionAsync(DeductionInput x, CancellationToken t) => E(); public ValueTask<int> SaveLoanAsync(LoanInput x, CancellationToken t) => E(); public ValueTask<bool> AnnulAsync(string y, int n, CancellationToken t) => ValueTask.FromException<bool>(new InvalidOperationException("Recursos humanos no está configurado.")); }
